    "prompt": "Generate one distinct fictional adult Japanese handsome man, age 27. IDENTITY, highest priority: a petite round face, very short midface and lower face, small curved jaw and short rounded chin; round through short proportions, never heavy cheeks. Eyes: round eyes with tall vertical apertures; level eye corners; monolids with no visible upper-lid fold; small eye apertures relative to the face; balanced eye spacing; moderate lower-lid fullness. Brows: medium-width eyebrows; gently curved brow contours; distinctly rising eyebrows; brows close above the eyes. Nose: a low softly defined nasal bridge; a slender natural nose width; a visibly rounded nose tip. Mouth: a slightly narrow mouth; slender lips with restrained volume; an upper lip clearly thinner than the lower lip; a moderate Cupid bow. Keep these anatomical contrasts clear and create an unrelated identity; do not average them into a generic idol face. High attractiveness through harmonious individual features and polished natural grooming. Naturally supported smooth cheeks, no sunken cheeks, no buccal hollows, no dark concave cheekbone shadows. Round faces remain petite with modest cheek fullness, no heavy puffiness or double chin. Normal slim neck. Mouth small to average, lips thin to moderate, no plumped lips. Hair: ordinary layered short black hair with a soft, loosely separated fringe falling naturally down over the eyebrows; wispy tips reach just below the eyebrows but stay out of the eyes; light natural volume and irregular strands, no bowl-cut outline and no blunt straight fringe. Dark brown irises, natural black hair, realistic skin texture. Minimal natural makeup, no winged eyeliner, no dramatic false lashes, no contour makeup, no facial hair, jewelry or glasses. Realistic editorial beauty photo, front-facing head level, eyes at camera, neutral expression, closed lips. Plain light-gray crew-neck shirt, neutral light-gray studio background, soft even frontal lighting. Vertical 3:4 portrait, full head, shoulders and mid-chest visible. Face from hairline to chin about 38 percent of image height, face center at 50 percent width and 38 percent height. Eyes and full cheek/jaw outline unobstructed. For downward fringe, allow partial eyebrow coverage with natural separated strands. No tight crop, no text, no watermark.",
